/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: item, mount, row, radios, cards, dimmed, describedBy
 *   Constants: nameOnly, replace, guestReuse, guestCreate, replaceLead
 * Tests
 *   - a shared identity names its Album entry and each track entry and needs a choice: a name match and a create are offered as cards and neither is chosen
 *   - choosing a card saves the whole decision set at once with six keys each, choosing the saved answer again sends nothing, and a disabled section dims and disables its cards
 *   - while a choice saves, cards holding keyboard focus stay focusable and dimmed and ignore choices until the section is enabled again
 *   - a bound identity reuses its record, marks it hidden, and offers keeping or replacing its different ID, which saves with the record's captured revision
 *   - MusicBrainz IDs and record ID endings show only on request
 *   - rows without a MusicBrainz ID of their own, which neither the lookup nor the captured Album supplied, offer no ID toggle even where a record or candidate has one
 *   - entries naming different Artists keep their own and offer reuse or create, never a replace
 *   - a preselected create shows chosen, is not folded and needs no answer
 *   - a record holding the identity's MusicBrainz ID is preselected and listed first, the other name candidates stay visible, and choosing the preselected card again sends no decision for the row
 *   - an unbound identity may replace the ID of a candidate only while no listed record holds its own
 *   - an Artist another identity of the same list is bound to or reuses is disabled with why, while one used only in another list stays choosable
 *   - a refused save keeps the choice marked unsaved, Save decisions sends it again, and the choice survives a new read until its identity is gone
 *   - the label row decides the label like an identity, with no list to share
 *   - a read that fails or runs out of time says so and is read again with Find matches
 *   - a saved reuse whose record changed since shows unchosen with a note, and another choice sends a set without it
 *   - one name with two MusicBrainz IDs is two rows: each shows its ID, and a record holding one of them is offered to the other by name only
 *   - a stale saved reuse shows no card chosen even where a card is preselected, and choosing the preselected card saves the set without it
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import type { CatalogReview } from './catalogReviewApi';
import { capturedCatalogReview, reviewJson, session, viewer } from './catalogReviewFixtures.testSupport';
import { guestCandidateId, guestHandle, leadHandle, leadMusicBrainzId, leadOtherMusicBrainzId, leadRecordId, reviewAfterLookup, reviewIdentityResponse } from './catalogReviewLookupFixtures.testSupport';
import type { ReviewIdentityResponse } from './catalogReviewLookupApi';
import { CatalogReviewIdentities } from './CatalogReviewIdentities';

/**
 * The identity rows of an existing-Album review on their own, the identity read answered per test: what each row covers, the
 * cards it offers in each state, what choosing one saves, and how unsaved choices meet a new read. All names and identifiers are
 * synthetic.
 */
const item = () => reviewAfterLookup(capturedCatalogReview());
function mount(read: () => ReviewIdentityResponse | Response = reviewIdentityResponse, disabled = false) {
  const fetch = vi.fn(async (path: string) => { const value = read(); return path.endsWith('/candidates') ? value instanceof Response ? value : reviewJson(value) : reviewJson({ code: 'unexpected' }, 500); });
  vi.stubGlobal('fetch', fetch);
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const onSave = vi.fn();
  const element = (value: CatalogReview, off: boolean) => <QueryClientProvider client={client}><CatalogReviewIdentities item={value} disabled={off} onSave={onSave} /></QueryClientProvider>;
  const view = render(element(item(), disabled));
  return { fetch, onSave, rerender: (value: CatalogReview, off = disabled) => view.rerender(element(value, off)), section: () => screen.getByRole('region', { name: 'Artists and label' }) };
}
/** The card of the row whose heading starts with `name`. */
const row = async (name: string) => (await screen.findAllByRole('listitem')).find(item => (item.querySelector('strong, summary')?.textContent ?? '').startsWith(name))!;
const radios = (element: HTMLElement) => within(element).queryAllByRole('radio') as HTMLInputElement[];
/** Each choice card's title, whether it is chosen and whether it is disabled. */
const cards = (element: HTMLElement) => radios(element).map(radio => [radio.getAttribute('aria-label'), radio.checked, radio.disabled]);
/** Whether a card is dimmed as unavailable. */
const dimmed = (radio: HTMLElement) => radio.closest('label')!.style.opacity === '0.62';
const describedBy = (radio: HTMLElement) => document.getElementById(radio.getAttribute('aria-describedby') ?? '')?.textContent ?? '';
const nameOnly = 'Same name only; a matching name alone does not prove they are the same';
const replace = { scope: 'artist', identity: leadHandle, boundName: 'Synthetic catalog Artist', action: 'replace', candidateId: leadRecordId, candidateRevision: 'b'.repeat(64) } as const;
const guestReuse = { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'reuse', candidateId: guestCandidateId, candidateRevision: 'c'.repeat(64) } as const;
const guestCreate = { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'create-distinct', candidateId: null, candidateRevision: null } as const;
const replaceLead = /^Reuse the existing Synthetic catalog Artist and give it the MusicBrainz ID the lookup found$/;
beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('a shared identity names its Album entry and each track entry and needs a choice: a name match and a create are offered as cards and neither is chosen', async () => {
  const { section } = mount();
  expect(await within(section()).findByText(/^Each Artist is chosen once for the Album and every track that credits it, and a choice is saved at once\./)).toBeInTheDocument();
  const guest = await row('Synthetic guest');
  expect(guest.querySelector('details')).toBeNull();
  expect(within(guest).getByText('Needs a decision')).toBeInTheDocument();
  expect(within(guest).getAllByRole('listitem').map(entry => entry.textContent)).toEqual(['Album · Synthetic guest · Featured', '2 · Synthetic second track · Synthetic guest · Primary']);
  expect(within(guest).getByRole('radiogroup', { name: 'Synthetic guest' })).toBeInTheDocument();
  expect(cards(guest)).toEqual([['Reuse the existing Synthetic guest', false, false], ['Create Synthetic guest as new', false, false]]);
  expect(within(guest).getByRole('radio', { name: 'Reuse the existing Synthetic guest' })).toHaveAccessibleDescription(`Visibility: Public · ${nameOnly}`);
  expect(within(guest).getByRole('radio', { name: 'Create Synthetic guest as new' })).toHaveAccessibleDescription('Created with the Album\'s visibility: Public · Choose this when none of the above is the same');
  expect(within(guest).queryByRole('combobox')).not.toBeInTheDocument();
  expect(screen.getByText('1 Artist or label still needs a choice: reuse an existing one or create a new one.')).toHaveAttribute('role', 'status');
  expect(screen.queryByRole('button', { name: 'Save decisions' })).not.toBeInTheDocument();
});

test('choosing a card saves the whole decision set at once with six keys each, choosing the saved answer again sends nothing, and a disabled section dims and disables its cards', async () => {
  const { onSave } = mount(() => { const data = reviewIdentityResponse();
    data.identities[0] = { ...data.identities[0], needsAnswer: false, decision: { ...guestCreate, boundMusicBrainzId: null } };
    data.identities[1].decision = { ...replace, boundMusicBrainzId: leadMusicBrainzId }; return data; });
  const guest = await row('Synthetic guest');
  expect(within(guest).getByRole('radio', { name: 'Create Synthetic guest as new' })).toBeChecked();
  fireEvent.click(within(guest).getByRole('radio', { name: 'Reuse the existing Synthetic guest' }));
  expect(onSave).toHaveBeenCalledTimes(1);
  expect(onSave.mock.calls[0][0]).toEqual([guestReuse, replace]);
  expect(within(guest).getByRole('radio', { name: 'Reuse the existing Synthetic guest' })).toBeChecked();
  // Choosing the saved create again leaves nothing to save.
  fireEvent.click(within(guest).getByRole('radio', { name: 'Create Synthetic guest as new' }));
  expect(onSave).toHaveBeenCalledTimes(1);
  expect(within(guest).queryByText('Unsaved changes')).not.toBeInTheDocument();
  cleanup();
  // A disabled section (the draft has unsaved edits, say) dims and disables its cards, so none looks available; showing IDs changes
  // nothing stored, so it stays available.
  const locked = mount(reviewIdentityResponse, true);
  for (const radio of await screen.findAllByRole('radio')) { expect(radio).toBeDisabled(); expect(dimmed(radio)).toBe(true); }
  fireEvent.click(within(await row('Synthetic guest')).getByRole('radio', { name: 'Create Synthetic guest as new' }));
  expect(locked.onSave).not.toHaveBeenCalled();
  expect(within(await row('Synthetic guest')).getByRole('radio', { name: 'Create Synthetic guest as new' })).not.toBeChecked();
  expect(screen.getByRole('button', { name: 'Show MusicBrainz IDs' })).toBeEnabled();
});

test('while a choice saves, cards holding keyboard focus stay focusable and dimmed and ignore choices until the section is enabled again', async () => {
  const { onSave, rerender } = mount();
  const guest = await row('Synthetic guest'), create = within(guest).getByRole('radio', { name: 'Create Synthetic guest as new' });
  expect(radios(guest).some(dimmed)).toBe(false);
  act(() => create.focus());
  fireEvent.click(create);
  expect(onSave).toHaveBeenCalledTimes(1);
  // The save runs: disabling the focused card would drop keyboard focus, so the cards stay focusable, say they are unavailable and
  // look it.
  rerender(item(), true);
  expect(create).toHaveFocus();
  for (const radio of radios(guest)) { expect(radio).toBeEnabled(); expect(radio).toHaveAttribute('aria-disabled', 'true'); expect(dimmed(radio)).toBe(true); }
  fireEvent.click(within(guest).getByRole('radio', { name: 'Reuse the existing Synthetic guest' }));
  expect(onSave).toHaveBeenCalledTimes(1);
  expect(create).toBeChecked();
  // Focus leaves the cards while the section is still disabled: they are disabled like any other control.
  act(() => create.blur());
  for (const radio of radios(guest)) expect(radio).toBeDisabled();
  rerender(item(), false);
  for (const radio of radios(guest)) { expect(radio).toBeEnabled(); expect(radio).not.toHaveAttribute('aria-disabled'); expect(dimmed(radio)).toBe(false); }
});

test('a bound identity reuses its record, marks it hidden, and offers keeping or replacing its different ID, which saves with the record\'s captured revision', async () => {
  const { onSave } = mount();
  const lead = await row('Synthetic catalog Artist');
  expect(lead.querySelector('summary')!.textContent).toBe('Synthetic catalog Artist · Reuses the existing Synthetic catalog Artist · Visibility: Hidden');
  expect(within(lead).getByRole('radiogroup', { name: 'Synthetic catalog Artist' })).toBeInTheDocument();
  expect(cards(lead)).toEqual([['Keep its current MusicBrainz ID', true, false], ['Reuse the existing Synthetic catalog Artist and give it the MusicBrainz ID the lookup found', false, false]]);
  expect(within(lead).getByRole('radio', { name: 'Keep its current MusicBrainz ID' })).toHaveAccessibleDescription('Default choice');
  expect(within(lead).getByRole('radio', { name: replaceLead })).toHaveAccessibleDescription('Visibility: Hidden');
  fireEvent.click(within(lead).getByRole('radio', { name: replaceLead }));
  expect(onSave).toHaveBeenCalledWith([replace]);
  cleanup();
  // A bound record that keeps no other ID offers no choice; the ID applying records is said in words.
  mount(() => { const data = reviewIdentityResponse(); data.identities[1].bound[0].musicBrainzId = null;
    data.identities[1].musicBrainzIdWrite = { scope: 'artist', identity: leadHandle, musicBrainzId: leadMusicBrainzId, replaces: null }; return data; });
  const recorded = await row('Synthetic catalog Artist');
  expect(radios(recorded)).toEqual([]);
  expect(within(recorded).getByText('Updating the original Album also saves the MusicBrainz ID the lookup found on it')).toBeInTheDocument();
});

test('MusicBrainz IDs and record ID endings show only on request', async () => {
  const guestId = '00000000-0000-4000-8000-0000000000c9', keptId = '00000000-0000-4000-8000-0000000000d1';
  const { section } = mount(() => { const data = reviewIdentityResponse(); data.identities[0].musicBrainzId = guestId;
    data.candidates.items[0] = { ...data.candidates.items[0], musicBrainzId: keptId }; return data; });
  const guest = await row('Synthetic guest'), lead = await row('Synthetic catalog Artist'), toggle = screen.getByRole('button', { name: 'Show MusicBrainz IDs' });
  expect(section().textContent).not.toMatch(/[0-9a-f]{8}-[0-9a-f]{4}-/);
  expect(section().textContent).not.toContain(guestCandidateId.slice(-6));
  expect(toggle).toHaveAttribute('aria-pressed', 'false');
  expect(cards(guest).map(([name]) => name)).toEqual(['Reuse the existing Synthetic guest', 'Reuse the existing Synthetic guest and give it the MusicBrainz ID the lookup found', 'Create Synthetic guest as new']);
  expect(describedBy(radios(guest)[0])).toBe(`Visibility: Public · ${nameOnly} · It already has another MusicBrainz ID and keeps it`);
  fireEvent.click(toggle);
  expect(toggle).toHaveAttribute('aria-pressed', 'true');
  expect(lead.querySelector('summary')!.textContent).toBe(`Synthetic catalog Artist · MusicBrainz ID ${leadMusicBrainzId} · Reuses the existing Synthetic catalog Artist · Visibility: Hidden`);
  expect(cards(lead).map(([name]) => name)).toEqual([`Keep its MusicBrainz ID ${leadOtherMusicBrainzId}`,
    `Reuse Synthetic catalog Artist and replace its MusicBrainz ID ${leadOtherMusicBrainzId} with ${leadMusicBrainzId}`]);
  expect(describedBy(radios(lead)[1])).toBe(`Visibility: Hidden · ID ending ${leadRecordId.slice(-6)}`);
  expect(guest.querySelector('strong')!.textContent).toBe(`Synthetic guest · MusicBrainz ID ${guestId}`);
  expect(describedBy(radios(guest)[0])).toBe(`Visibility: Public · ${nameOnly} · keeps its MusicBrainz ID ${keptId} · ID ending ${guestCandidateId.slice(-6)}`);
  expect(radios(guest)[1]).toHaveAttribute('aria-label', `Reuse Synthetic guest and replace its MusicBrainz ID ${keptId} with ${guestId}`);
  cleanup();
  // Nothing carries an ID: no toggle.
  mount(() => { const data = reviewIdentityResponse(); data.identities[1].musicBrainzId = null; data.identities[1].bound[0].musicBrainzId = null; return data; });
  await row('Synthetic guest');
  expect(screen.queryByRole('button', { name: 'Show MusicBrainz IDs' })).not.toBeInTheDocument();
});

test('rows without a MusicBrainz ID of their own, which neither the lookup nor the captured Album supplied, offer no ID toggle even where a record or candidate has one', async () => {
  const { section } = mount(() => { const data = reviewIdentityResponse(); data.identities = data.identities.map(identity => ({ ...identity, musicBrainzId: null }));
    data.candidates.items[0] = { ...data.candidates.items[0], musicBrainzId: '00000000-0000-4000-8000-0000000000d1' }; return data; });
  const guest = await row('Synthetic guest'), lead = await row('Synthetic catalog Artist');
  expect(screen.queryByRole('button', { name: 'Show MusicBrainz IDs' })).not.toBeInTheDocument();
  // The bound record keeps its own ID without a choice, and the candidate's ID is not offered for replacing.
  expect(radios(lead)).toEqual([]);
  expect(cards(guest).map(([name]) => name)).toEqual(['Reuse the existing Synthetic guest', 'Create Synthetic guest as new']);
  expect(section().textContent).not.toMatch(/[0-9a-f]{8}-[0-9a-f]{4}-|MusicBrainz ID/);
});

test('entries naming different Artists keep their own and offer reuse or create, never a replace', async () => {
  mount(() => { const data = reviewIdentityResponse(); data.identities[1] = { ...data.identities[1], state: 'conflicting', needsAnswer: true,
    bound: [data.identities[1].bound[0], { ...data.identities[1].bound[0], id: 'f'.repeat(24), name: 'Synthetic other Artist', visibility: 'public' }] };
    data.candidates.items.push({ ...data.candidates.items[0], id: 'd'.repeat(24), label: 'Synthetic catalog Artist', musicBrainzId: leadOtherMusicBrainzId }); return data; });
  const lead = await row('Synthetic catalog Artist');
  expect(lead.querySelector('details')).toBeNull();
  expect(within(lead).getByText(/^These credits name different Artists, so each keeps its own and no MusicBrainz ID is saved\./)).toBeInTheDocument();
  expect(within(lead).getAllByRole('listitem').map(item => item.textContent)).toContain(`Synthetic catalog Artist · Visibility: Hidden · ${leadRecordId.slice(-6)}`);
  expect(cards(lead).map(([name]) => name)).toEqual(['Reuse the existing Synthetic catalog Artist', 'Create Synthetic catalog Artist as new']);
  expect(describedBy(radios(lead)[0])).toBe(`Visibility: Public · ${nameOnly} · It already has another MusicBrainz ID and keeps it`);
});

test('a preselected create shows chosen, is not folded and needs no answer', async () => {
  mount(() => { const data = reviewIdentityResponse();
    data.identities[0] = { ...data.identities[0], needsAnswer: false, preselection: { ...guestCreate } };
    data.candidates.items = []; return data; });
  const guest = await row('Synthetic guest');
  expect(guest.querySelector('details')).toBeNull();
  expect(cards(guest)).toEqual([['Create Synthetic guest as new', true, false]]);
  expect(describedBy(radios(guest)[0])).toBe('Created with the Album\'s visibility: Public · No existing Artist or label was found to reuse · Default choice');
  expect(screen.queryByText(/^Artists or labels to choose/)).not.toBeInTheDocument();
});

test('a record holding the identity\'s MusicBrainz ID is preselected and listed first, the other name candidates stay visible, and choosing the preselected card again sends no decision for the row', async () => {
  const guestId = '00000000-0000-4000-8000-0000000000c9';
  const read = (stored: boolean) => () => { const data = reviewIdentityResponse(), holder = { ...data.candidates.items[0], id: 'e'.repeat(24), match: 'musicBrainzId' as const, musicBrainzId: guestId };
    data.identities[0] = { ...data.identities[0], musicBrainzId: guestId, needsAnswer: false, preselection: { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'reuse',
      candidateId: holder.id, candidateRevision: holder.revision }, decision: stored ? { ...guestReuse, boundMusicBrainzId: guestId } : null };
    data.candidates.items.push(holder); return data; };
  const { onSave } = mount(read(false));
  const guest = await row('Synthetic guest');
  expect(guest.querySelector('details')).toBeNull();
  // Both records carry the same name, so their ID endings tell them apart.
  expect(cards(guest)).toEqual([['Reuse the existing Synthetic guest', true, false], ['Reuse the existing Synthetic guest', false, false], ['Create Synthetic guest as new', false, false]]);
  expect(radios(guest).map(describedBy)).toEqual([`Visibility: Public · Same MusicBrainz ID as the lookup found · Default choice · ID ending ${'e'.repeat(6)}`,
    `Visibility: Public · ${nameOnly} · ID ending ${guestCandidateId.slice(-6)}`,
    'Created with the Album\'s visibility: Public · The new one gets no MusicBrainz ID, since an existing one already has it']);
  fireEvent.click(radios(guest)[1]);
  expect(onSave).toHaveBeenLastCalledWith([guestReuse]);
  cleanup();
  const stored = mount(read(true));
  const decided = await row('Synthetic guest');
  expect(radios(decided)[1]).toBeChecked();
  fireEvent.click(radios(decided)[0]);
  expect(stored.onSave).toHaveBeenLastCalledWith([]);
});

test('an unbound identity may replace the ID of a candidate only while no listed record holds its own', async () => {
  const id = '00000000-0000-4000-8000-0000000000c9';
  const withId = (holder: boolean) => () => { const data = reviewIdentityResponse(); data.identities[0] = { ...data.identities[0], musicBrainzId: id };
    data.candidates.items[0] = { ...data.candidates.items[0], musicBrainzId: '00000000-0000-4000-8000-0000000000d1' };
    if (holder) data.candidates.items.push({ ...data.candidates.items[0], id: 'e'.repeat(24), match: 'musicBrainzId', musicBrainzId: id }); return data; };
  const { onSave } = mount(withId(false));
  const replaceable = await row('Synthetic guest');
  expect(radios(replaceable)[1]).toHaveAttribute('aria-label', 'Reuse the existing Synthetic guest and give it the MusicBrainz ID the lookup found');
  expect(describedBy(radios(replaceable)[1])).toBe(`Visibility: Public · ${nameOnly}`);
  fireEvent.click(radios(replaceable)[1]);
  expect(onSave).toHaveBeenLastCalledWith([{ ...guestReuse, action: 'replace' }]);
  cleanup();
  mount(withId(true));
  const held = cards(await row('Synthetic guest')).map(([name]) => String(name));
  expect(held.some(name => name.includes('give it the MusicBrainz ID'))).toBe(false);
  expect(held).toEqual(['Reuse the existing Synthetic guest', 'Reuse the existing Synthetic guest', 'Create Synthetic guest as new']);
});

test('an Artist another identity of the same list is bound to or reuses is disabled with why, while one used only in another list stays choosable', async () => {
  const read = (shared: boolean) => () => { const data = reviewIdentityResponse();
    data.candidates.items.push({ ...data.candidates.items[0], id: leadRecordId, label: 'Synthetic guest' });
    if (!shared) data.identities[1].entries = [{ ...data.identities[1].entries[0], path: 'tracks.10000000-0000-4000-8000-000000000001.artists', slotId: '10000000-0000-4000-8000-000000000001' }];
    return data; };
  const leadCard = (element: HTMLElement) => radios(element).find(radio => describedBy(radio).includes(`ID ending ${leadRecordId.slice(-6)}`))!;
  mount(read(true));
  const taken = leadCard(await row('Synthetic guest'));
  expect(taken).toBeDisabled();
  expect(describedBy(taken)).toBe(`Visibility: Public · ${nameOnly} · ID ending ${leadRecordId.slice(-6)} · Already used for another Artist in this list`);
  cleanup();
  mount(read(false));
  expect(leadCard(await row('Synthetic guest'))).toBeEnabled();
});

test('a refused save keeps the choice marked unsaved, Save decisions sends it again, and the choice survives a new read until its identity is gone', async () => {
  let data = reviewIdentityResponse();
  const { rerender, onSave, fetch } = mount(() => data);
  fireEvent.click(within(await row('Synthetic guest')).getByRole('radio', { name: 'Create Synthetic guest as new' }));
  expect(onSave).toHaveBeenCalledTimes(1);
  // No read stores the choice (the save was refused): it stays chosen and unsaved, and Save decisions sends the same set again.
  expect(within(await row('Synthetic guest')).getByText('Unsaved changes')).toBeInTheDocument();
  fireEvent.click(screen.getByRole('button', { name: 'Save decisions' }));
  expect(onSave.mock.calls).toEqual([[[guestCreate]], [[guestCreate]]]);
  // A lookup application advances the value revision: the rows are read again and the choice is kept.
  rerender({ ...item(), valueRevision: item().valueRevision + 1 });
  await waitFor(() => expect(fetch).toHaveBeenCalledTimes(2));
  await waitFor(() => expect(screen.getByRole('button', { name: 'Save decisions' })).toBeEnabled());
  expect(within(await row('Synthetic guest')).getByRole('radio', { name: 'Create Synthetic guest as new' })).toBeChecked();
  // The identity is gone from the next read: its choice is dropped.
  data = { ...reviewIdentityResponse(), identities: [reviewIdentityResponse().identities[1]] };
  rerender({ ...item(), valueRevision: item().valueRevision + 2 });
  await waitFor(() => expect(fetch).toHaveBeenCalledTimes(3));
  await waitFor(() => expect(screen.queryByRole('radio', { name: 'Create Synthetic guest as new' })).not.toBeInTheDocument());
  data = reviewIdentityResponse();
  rerender({ ...item(), valueRevision: item().valueRevision + 3 });
  await waitFor(() => expect(fetch).toHaveBeenCalledTimes(4));
  expect(within(await row('Synthetic guest')).getByRole('radio', { name: 'Create Synthetic guest as new' })).not.toBeChecked();
  expect(screen.queryByRole('button', { name: 'Save decisions' })).not.toBeInTheDocument();
  expect(screen.queryByText('Unsaved changes')).not.toBeInTheDocument();
  expect(onSave).toHaveBeenCalledTimes(2);
});

test('the label row decides the label like an identity, with no list to share', async () => {
  const { onSave } = mount(() => ({ ...reviewIdentityResponse(), identities: [], label: { name: 'Synthetic Label', musicBrainzId: null, state: 'unbound', bound: null, decision: null, preselection: null,
    needsAnswer: true, musicBrainzIdWrite: null }, candidates: { items: [{ ...reviewIdentityResponse().candidates.items[0], kind: 'organization', label: 'Synthetic Label', id: 'a'.repeat(24) }], unavailable: [] } }));
  const label = await row('Label · Synthetic Label');
  expect(cards(label).map(([name]) => name)).toEqual(['Reuse the existing Synthetic Label', 'Create Synthetic Label as new']);
  fireEvent.click(within(label).getByRole('radio', { name: 'Reuse the existing Synthetic Label' }));
  expect(onSave).toHaveBeenCalledWith([{ scope: 'label', identity: null, boundName: 'Synthetic Label', action: 'reuse', candidateId: 'a'.repeat(24), candidateRevision: 'c'.repeat(64) }]);
});

test('a read that fails or runs out of time says so and is read again with Find matches', async () => {
  let fail = true;
  const { fetch, section } = mount(() => fail ? reviewJson({ code: 'ADMIN_IMPORT_CANDIDATES_TIMEOUT' }, 503) : reviewIdentityResponse());
  expect(await within(section()).findByRole('alert')).toHaveTextContent('The request could not be confirmed. Your saved draft is retained.');
  fail = false;
  fireEvent.click(within(section()).getByRole('button', { name: 'Find matches' }));
  expect(await row('Synthetic guest')).toBeTruthy();
  expect(fetch).toHaveBeenCalledTimes(2);
});

test('a saved reuse whose record changed since shows unchosen with a note, and another choice sends a set without it', async () => {
  const { onSave } = mount(() => { const data = reviewIdentityResponse();
    data.identities[0].decision = { ...guestReuse, boundMusicBrainzId: null, candidateRevision: 'e'.repeat(64) };
    return data; });
  const guest = await row('Synthetic guest');
  expect(within(guest).getByText('The Artist or label chosen earlier has changed since. Choose again.')).toBeInTheDocument();
  expect(radios(guest).some(radio => radio.checked)).toBe(false);
  // Another row's choice alone: the stale reuse is left out of the whole set each save replaces.
  fireEvent.click(within(await row('Synthetic catalog Artist')).getByRole('radio', { name: replaceLead }));
  expect(onSave).toHaveBeenLastCalledWith([replace]);
  // The changed record, listed at its new revision, can be chosen again, and that choice is sent at the new revision.
  fireEvent.click(within(guest).getByRole('radio', { name: 'Reuse the existing Synthetic guest' }));
  expect(within(guest).queryByText(/^The Artist or label chosen earlier/)).not.toBeInTheDocument();
  expect(onSave).toHaveBeenLastCalledWith([guestReuse, replace]);
});

test('one name with two MusicBrainz IDs is two rows: each shows its ID, and a record holding one of them is offered to the other by name only', async () => {
  const firstId = '00000000-0000-4000-8000-0000000000e1', secondId = '00000000-0000-4000-8000-0000000000e2', otherHandle = '70000000-0000-4000-8000-000000000003';
  mount(() => { const data = reviewIdentityResponse(), guest = data.identities[0];
    data.identities = [{ ...guest, musicBrainzId: secondId }, { ...guest, id: otherHandle, musicBrainzId: firstId, entries: [guest.entries[1]], preselection: null }, data.identities[1]];
    // The server lists the record once, by its strongest match over every row: the ID of the second row.
    data.candidates.items.push({ ...data.candidates.items[0], id: 'e'.repeat(24), match: 'musicBrainzId', musicBrainzId: firstId }); return data; });
  const [second, first] = await screen.findAllByRole('radiogroup', { name: /^Synthetic guest/ });
  // With MusicBrainz IDs hidden, the rows' headings still show them.
  expect([second, first].map(group => group.getAttribute('aria-labelledby')).map(heading => document.getElementById(heading!)!.textContent))
    .toEqual([`Synthetic guest · MusicBrainz ID ${secondId}`, `Synthetic guest · MusicBrainz ID ${firstId}`]);
  // On the row whose ID it does not hold, the record is a name match, listed in the server's order and never first for its ID.
  expect(radios(second).map(describedBy)).toEqual([`Visibility: Public · ${nameOnly} · ID ending ${guestCandidateId.slice(-6)}`,
    `Visibility: Public · ${nameOnly} · It already has another MusicBrainz ID and keeps it · ID ending ${'e'.repeat(6)}`,
    `Visibility: Public · ${nameOnly} · ID ending ${'e'.repeat(6)}`, 'Created with the Album\'s visibility: Public · Choose this when none of the above is the same']);
  expect(radios(first).map(describedBy)[0]).toBe(`Visibility: Public · Same MusicBrainz ID as the lookup found · ID ending ${'e'.repeat(6)}`);
});

test('a stale saved reuse shows no card chosen even where a card is preselected, and choosing the preselected card saves the set without it', async () => {
  const guestId = '00000000-0000-4000-8000-0000000000c9', holderId = 'e'.repeat(24);
  // The stored reuse names the record holding the identity's MusicBrainz ID at a revision it no longer has.
  const { onSave } = mount(() => { const data = reviewIdentityResponse(), holder = { ...data.candidates.items[0], id: holderId, match: 'musicBrainzId' as const, musicBrainzId: guestId };
    data.identities[0] = { ...data.identities[0], musicBrainzId: guestId, needsAnswer: true, preselection: { ...guestReuse, candidateId: holderId, candidateRevision: holder.revision },
      decision: { ...guestReuse, candidateId: holderId, candidateRevision: 'f'.repeat(64), boundMusicBrainzId: guestId } };
    data.candidates.items.push(holder); return data; });
  const guest = await row('Synthetic guest');
  expect(within(guest).getByText('The Artist or label chosen earlier has changed since. Choose again.')).toBeInTheDocument();
  expect(radios(guest).some(radio => radio.checked)).toBe(false);
  fireEvent.click(radios(guest)[0]);
  expect(onSave).toHaveBeenLastCalledWith([]);
  expect(radios(guest)[0]).toBeChecked();
  cleanup();
  // A stale reuse whose record is no longer listed, with create preselected: the only card is not chosen and saves when chosen.
  const created = mount(() => { const data = reviewIdentityResponse();
    data.identities[0] = { ...data.identities[0], needsAnswer: true, preselection: { ...guestCreate }, decision: { ...guestReuse, boundMusicBrainzId: null } };
    data.candidates.items = []; return data; });
  const only = await row('Synthetic guest');
  expect(cards(only)).toEqual([['Create Synthetic guest as new', false, false]]);
  fireEvent.click(radios(only)[0]);
  expect(created.onSave).toHaveBeenLastCalledWith([]);
});
